// slot before the dword push.
struct CTCBase;

struct SComponentPair {                              // pair<ETCInterfaceType, CTCBase*>, 8 bytes
    long     first;
    CTCBase* second;
};

struct CCallOnDie {                                  // empty functor: p.second->OnDie()
    void operator()(SComponentPair& p) const;
